FusedMultiplySubtractScalarBySelectedScalar(v64f32,v64f32,v64f32,u8) @imm[0..2) = dn2cpp_isa_lane0<8>(vfmss_lane_f32(vget_lane_f32($0, 0), vget_lane_f32($1, 0), $2, $3))
MultiplyByScalar(v128f64,v64f64) = vmulq_lane_f64($0, $1, 0)
